// static imports: MockMvcRequestBuilders.*, MockMvcResultMatchers.*, Mockito.when
@WebMvcTest(UserController.class)
class UserControllerTest {
    @Autowired MockMvc mvc;
    @MockitoBean UserService service;

    @Test
    void returnsTheUser() throws Exception {
        when(service.find(1L)).thenReturn(new UserResponse(1L, "Ana"));

        mvc.perform(get("/users/1"))
           .andExpect(status().isOk())
           .andExpect(jsonPath("$.name").value("Ana"));
    }

    @Test
    void rejectsInvalidInput() throws Exception {
        mvc.perform(post("/users").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"\"}"))
           .andExpect(status().isBadRequest());
    }
}

