@Configuration
public class SecurityConfig {
    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth
              .requestMatchers("/public/**").permitAll()
              .requestMatchers("/admin/**").hasRole("ADMIN")
              .anyRequest().authenticated())
            .httpBasic(Customizer.withDefaults());
        return http.build();
    }

    @Bean // prototype only: in-memory users
    public UserDetailsService users() {
        return new InMemoryUserDetailsManager(
            User.withUsername("ana").password("{noop}secret").roles("USER").build(),
            User.withUsername("admin").password("{noop}secret").roles("ADMIN").build());
    }
}

// WRONG: startup fails — "Can't configure requestMatchers after anyRequest"
